use lapis_app_protocol::database::{
    call::{DatabaseCall, DatabaseMethod, DatabaseValue},
    changes::{ChangeDomain, ChangeSet, ChangedPath},
    search::source::SearchChunkingSettings,
};
use ts_rs::{Config, TS};

pub(super) fn typescript(config: &Config) -> String {
    format!(
        "// Generated by pnpm protocol:generate. Do not edit.\n{}\n",
        [
            DatabaseMethod::decl(config),
            DatabaseValue::decl(config),
            DatabaseCall::decl(config),
            ChangeDomain::decl(config),
            ChangedPath::decl(config),
            ChangeSet::decl(config),
            SearchChunkingSettings::decl(config),
        ]
        .iter()
        .map(|item| format!("export {item}"))
        .collect::<Vec<_>>()
        .join("\n")
    )
}
